alter table lti_registration drop index ux_lti_registration_education_resource, drop index ux_lti_registration_issuer, add unique key ux_lti_registration_issuer_client (issuer, client_id), modify jwks_uri varchar(1024) null, add column platform_public_key varchar(2048) null after jwks_uri, add column method varchar(20) not null default 'LINK' after deployment_id;
